//! Per-control reporting uses the real App required-field editor path.
use super::*;
struct Fixture(std::path::PathBuf);impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
fn node(app:&App,id:&str)->usize{(0..app.document.nodes.len()).find(|&n|app.document.attr(n,"id")==Some(id)).unwrap()}
fn click(app:&mut App,n:usize){let r=app.page.controls.iter().find(|r|r.node==n).unwrap();let(x,y)=(r.x+r.width/2,app.content_top()+r.y+r.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);}
#[test]
fn control_validation_actual_app_readonly_report_editing_paint_layout_and_links(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-app-control-validation-{}.html",std::process::id())));std::fs::write(&file.0,r#"<!doctype html><style>input,button{display:block}#paint{position:absolute;left:420px;top:160px;width:40px;height:30px;background:#114455}#paint.done{background:#cc2244}#stable{position:absolute;left:420px;top:100px}</style><form id=form><input id=field name=q required><datalist><input id=listed required></datalist></form><button id=go name=go type=button>Toggle</button><input id=neighbor value=neighbor><a id=stable href=#destination>Go</a><div id=paint></div><div id=destination></div><script>var form=document.getElementById('form'),field=document.getElementById('field'),round=0,invalid=0;form.addEventListener('invalid',function(e){if(e.target!==field||!e.isTrusted)throw 'candidate event';invalid++;},true);document.getElementById('go').onclick=function(){if(round===0){field.readOnly=true;if(field.willValidate||!field.checkValidity()||field.validationMessage!==''||invalid)throw 'barred field';document.title='Barred';}else if(round===1){field.readOnly=false;if(!field.willValidate||field.validationMessage!=="Complete the required field: q."||field.reportValidity()!==false||invalid!==1)throw 'candidate required';document.title='Candidate';}else{if(!field.willValidate||field.validationMessage!==''||field.reportValidity()!==true||invalid!==1)throw 'candidate valid';document.getElementById('paint').className='done';document.title='Valid';}round++;};</script>"#).unwrap();let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);let field=node(&app,"field");let go=node(&app,"go");let neighbor=node(&app,"neighbor");let stable=node(&app,"stable");let raw=app.raw.clone();let location=app.location.clone();let epoch=app.script_epoch;let r=app.page.controls.iter().find(|r|r.node==field).unwrap();let rect=(r.x,r.y,r.width,r.height);app.forms.script_set_value(neighbor,"neighbor edit").unwrap();{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}let before=app.draw();click(&mut app,go);assert_eq!(app.document.title,"Barred");assert!(!app.failed);click(&mut app,go);assert_eq!(app.document.title,"Candidate");assert!(app.failed);assert_eq!(app.status,"Complete the required field: q.");assert!(matches!(app.focus,Focus::Control(n)if n==field));for ch in ['A','😀','Z']{app.text_input(ch);}click(&mut app,go);assert_eq!(app.document.title,"Valid");assert!(!app.failed&&!app.is_loading());assert!(app.status.is_empty());assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());let painted=app.draw();let pixel=(app.content_top()+170)as usize*painted.width+430;assert_eq!(painted.pixels[pixel],0xcc2244);assert_ne!(before.pixels[pixel],painted.pixels[pixel]);let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("neighbor edit".into(),5,2,1));let r=app.page.controls.iter().find(|r|r.node==field).unwrap();assert_eq!((r.x,r.y,r.width,r.height),rect);assert_eq!(app.page.link_node_at(430,110),Some(stable));assert_eq!((app.raw.clone(),app.location.clone(),app.script_epoch),(raw,location,epoch));
}
